use vstd::prelude::*;

verus! {
    // Predicate: v is non-empty and sorted non-decreasingly
    spec fn sorted(v: &Vec<u64>) -> bool {
        forall|i: int, j: int|
            0 <= i && i <= j && j < v.len() ==> v[i] <= v[j]
    }

    // Predicate: target k is in v between indices l and r (inclusive)
    spec fn contains(v: &Vec<u64>, l: int, r: int, k: u64) -> bool {
        exists|i: int| l <= i && i <= r && i < v.len() && v[i] == k
    }

    fn binary_search(v: &Vec<u64>, k: u64) -> (r: usize)
        requires
            v.len() > 0,
            sorted(v),
            contains(v, 0, (v.len() as int)-1, k),
        ensures
            r < v.len(),
            v[r] == k
    {
        // Use integers for indices for easy reasoning, cast to usize when returning.
        let mut l: int = 0;
        let mut r_ind: int = (v.len() as int) - 1;

        while l < r_ind
            invariant
                0 <= l && r_ind < v.len() as int,
                l <= r_ind,
                sorted(v),
                contains(v, l, r_ind, k),
            decreases r_ind - l,
        {
            let mid = (l + r_ind) / 2;

            if v[mid as usize] < k {
                // Target must be strictly to the right of mid
                l = mid + 1;
            } else {
                // Target is at mid or to the left
                r_ind = mid;
            }
        }

        // When loop ends, l == r_ind and contains(v, l, r_ind, k) implies v[l] == k
        // Because interval size 1 contains k.

        let result = l as usize;
        assert(result < v.len());
        assert(v[result] == k);
        result
    }
}
